//
// pocket_video — emu video output (CLK_VIDEO + CE_PIXEL + VGA_*) to the
// Pocket scaler (real pixel clock, pulse syncs, RGB=0 outside DE).
//
// Pixel clock: generated by registers in the CLK_VIDEO domain, locked to
// CE_PIXEL. P = cycles between two CEs (measured), Q = P/4. The data changes on
// CE (count 0); video_rgb_clock is high in counts [Q, 3Q), so both of its edges
// are at least Q cycles away from any data change; the 90-degree clock is high
// in [2Q, P). Example: P = 16 (80 MHz / 5 MHz), Q = 4 = 50 ns of margin.
//
// Pocket rules followed (bus-communication documentation):
//   - HS: a single cycle per line, on the HSync start edge;
//   - VS: a single cycle per frame, on the first HSync END edge after the
//     start of VSync -> never less than 3 cycles before an HS;
//   - RGB = 0 outside DE, except for the "Set Scaler Slot" command word
//     {8'h0, slot[2:0], 13'h0} in the blanking (as jtframe does); in the VS
//     cycle RGB = 0 (bits [23:4] must be 0).

module pocket_video #(
	parameter HS_POL = 1,          // 1 = HSync active high
	parameter VS_POL = 1
)(
	input             clk,         // CLK_VIDEO
	input             ce_pix,      // CE_PIXEL
	input       [7:0] r, g, b,
	input             hs, vs, de,
	input       [2:0] slot,        // scaler slot (quasi-static, other clock domain)

	output reg [23:0] rgb_o = 0,
	output reg        de_o = 0,
	output reg        hs_o = 0,
	output reg        vs_o = 0,
	output reg        pclk = 0,
	output reg        pclk90 = 0
);

reg [2:0] slot_s1, slot_s2;
always @(posedge clk) begin slot_s1 <= slot; slot_s2 <= slot_s1; end

wire hsa = HS_POL ? hs : ~hs;
wire vsa = VS_POL ? vs : ~vs;

reg       hs_prev = 0, vs_prev = 0, vs_pend = 0;
reg [7:0] cnt = 0, per = 0;

wire [7:0] cnt_n = ce_pix ? 8'd0 : ((cnt == 8'hFF) ? cnt : cnt + 8'd1);
wire [7:0] q     = {2'b00, per[7:2]};

always @(posedge clk) begin
	cnt <= cnt_n;
	if (ce_pix) per <= cnt + 8'd1;

	pclk   <= (q != 0) && (cnt_n >= q) && (cnt_n < (q + q + q));
	pclk90 <= (q != 0) && (cnt_n >= (q + q));

	if (ce_pix) begin
		hs_prev <= hsa;
		vs_prev <= vsa;

		hs_o <= hsa & ~hs_prev;

		if (vsa & ~vs_prev) vs_pend <= 1;
		vs_o <= 0;
		if (vs_pend & hs_prev & ~hsa) begin
			vs_o    <= 1;
			vs_pend <= 0;
		end

		de_o <= de;
		if (de)
			rgb_o <= {r, g, b};
		else if (vs_pend & hs_prev & ~hsa)
			rgb_o <= 24'd0;
		else
			rgb_o <= {8'h00, slot_s2, 13'h0000};
	end
end

endmodule
